=== PROP 1 ===

\subsubsection*{The Frozen Paradox: full fine-tuning loses by $12$--$79\%$}

{\looseness=-1 Within a fixed MoE architecture, does freezing match or beat fine-tuning (\emph{RQ1})? Frozen RR-MoA beats \emph{full fine-tuning} (all 8 blocks, best of 5 heads $\times$ 2 LRs) by $12$--$79\%$ on all 6 LTSF datasets (Figure~\ref{fig:frozen_paradox}). The headline gap decomposes into \emph{(M1)} an MoE architectural advantage ($26$--$79\%$, Table~\ref{tab:rrmoa}) and \emph{(M2)} a smaller within-architecture freeze effect ($\leq 13\%$; frozen best on $4/6$, light unfreezing wins by ${\leq}13\%$ on the other two; SR-MoA replicates $4/6$, Table~\ref{tab:self_routed}). Proposition~\ref{prop:frozen} attributes M2 to gradient co-adaptation: a Router-Detached Gradient Flow ablation degrades MSE by $+35$--$100\%$ (Appendix~\ref{app:routing_ablations}), and disabling RevIN recovers full-FT by $54$--$61\%$ (Appendix~\ref{app:extended_ft}), pinning the mechanism on normalization. A $90$-config tune (LR $10^{-5}$--$10^{-6}$, $100$ epochs, cosine+warmup, layerwise decay) still loses by $51$--$71\%$.}

\begin{proposition}[Gradient Co-Adaptation Drives Entropy Collapse]
\label{prop:frozen}
Consider a $2$-expert MoE with backbone $\mathbf{h}{=}A\mathbf{x}$, router $p{=}\sigma(\mathbf{w}^\top\mathbf{h})$, loss $\ell{=}p\,\ell_1{+}(1{-}p)\,\ell_2$. Under gradient descent on $(A,\mathbf{w})$: \textup{(i)} the dominant expert's loss decreases faster ($\dot{\ell}_k \propto {-}p_k\|\nabla_\mathbf{h}\ell_k\|^2$), and $\dot{p}$ amplifies whichever expert currently has lower loss, creating self-reinforcing collapse toward $p{\in}\{0,1\}$; \textup{(ii)} freezing $A$ removes the co-adaptation feedback through the backbone (full non-collapse additionally requires $(\ell_1{-}\ell_2)$ to flip sign across input regimes, i.e., expert specialization, which is satisfied by the topologically distinct RR-MoA pool). Proof in Appendix~\ref{app:proofs}.
\end{proposition}

{\looseness=-1 \textit{Remark.} Proposition~\ref{prop:frozen} covers linear $A\mathbf{x}$; Figure~\ref{fig:trajectory}b confirms it in the full 8-block Transformer within ${\sim}50$ steps. Independent ensembles are $37$--$46\%$ worse (Table~\ref{tab:baselines}), so learned routing -- not mere diversity -- drives the gains. \S\ref{sec:mechanism} answered \emph{what} the router needs to read with Observation~\ref{obs:routing_loss} and the predictor $R(\mathcal{D})$; we now turn to the \emph{mechanism (RQ2)}.}

\subsubsection*{$R(\mathcal{D})$ makes three predictions, and all three hold}

Observation~\ref{obs:routing_loss} and $R(\mathcal{D})$ make three testable predictions: the bound is empirically tight, $R(\mathcal{D})$ predicts raw-routing benefit across datasets, and the predictor respects a falsifiable boundary distinct from a generic-SNR explanation. We verify each in turn (\emph{RQ2}).


=== PROP1 PROOF part ii ===
\end{proof}

\textbf{Corollary (Raw routing decouples the router from $A$).}
\label{cor:raw_routing}
\emph{If the router reads the raw input $\mathbf{x}_\mathrm{raw}$ rather than the hidden state $\mathbf{h} = A\mathbf{x}$, then $\partial p / \partial A \equiv 0$, the loss-coupling term in $\partial\ell/\partial A$ vanishes identically, and the co-adaptation feedback loop of Proposition~\ref{prop:frozen}(i) is broken \emph{by construction} regardless of whether $A$ is frozen.}

\begin{proof}[Proof of Corollary]
With router input $\mathbf{x}_\mathrm{raw}$ (independent of $A$), $p = \sigma(\mathbf{w}^\top G_\psi(\mathbf{x}_\mathrm{raw}))$ is a function of $\mathbf{x}_\mathrm{raw}$ and $(\mathbf{w}, \psi)$ only. Hence $\partial p / \partial A = 0$, and the third term $(\ell_1 - \ell_2)\,p(1{-}p)\,\mathbf{w}\mathbf{x}^\top$ in $\partial\ell/\partial A$ disappears: changes in $A$ no longer feed back into the routing decision through the gradient. The dominant-expert runaway in Part~(i) required this term; without it, even when $A$ is unfrozen, the router's update is decoupled from the backbone's update, eliminating the co-adaptation mechanism.
\end{proof}

This corollary identifies raw routing as the \emph{minimal causal intervention}: it intervenes on the precise term in $\partial\ell/\partial A$ that drives the collapse loop, leaving all other components of the model untouched. The empirical validation is in Figure~\ref{fig:trajectory} (RR-MoA's gradient norms remain balanced across experts even when blocks are unfrozen) and Table~\ref{tab:rrmoa} (frozen-vs-unfrozen RR-MoA both maintain healthy entropy, in contrast to AdaMix where unfreezing collapses entropy to $0.000$).

